import React from 'react';
import {Link} from 'react-router-dom';
// import {VscMenu, AiOutlineClose} from 'react-icons/all'
import logo from "../../../img/favicon.ico";
import './Navbar.css'
import '../../Button.css';
import {Button} from "../../Button";
import Popup from "../../Popup/Popup";
import SearchBar from "../../SearchBar";

function Navbar(props) {
    const{isHome, professorList, onChangeProfessor}=props;

    console.log(isHome)

    const TitlePopup = (props) => {
        const {titleText, onClose} = props;
        return (
            <div className={'title-popup'}>
                <div className={'title-text'}>{titleText}</div>
                <div className={'close-button'} onClick={onClose}>X</div>
            </div>
        )
    }

    const [isOpenLoginForm, setOpenLoginForm] = React.useState(false);

    const handleOpenLoginForm = () => {
        setOpenLoginForm(!isOpenLoginForm);
    }

    if(isHome){
        return (
            <>
                <div className="navbar">
                    <Link to='/' className="navbar-title">
                        <img src={logo} className={'logo'} alt={logo}/>
                        <div className={'title'}>UniAdvisor.it</div>
                    </Link>
                    <div className="menu-content">
                        <Button buttonStyle='btn--outline' onClick={handleOpenLoginForm}>ACCEDI/REGISTRATI</Button>
                        {isOpenLoginForm && <Popup>
                            <div className={'form-content'}>
                                <TitlePopup titleText={'Siamo spiacenti!'} onClose={handleOpenLoginForm}/>
                                <p>Il sito è in fase di manutenzione e questa funzione non è al momento disponibile.</p>
                                <p>Ti chiediamo di lasciarci la mail in modo da poterti avvisare quando è pronto</p>
                                <input className={"form-input"} placeholder="Mail"/>
                                <div className={'form-buttons'}>
                                    <button className={'send-button'}>Invia</button>
                                </div>
                            </div>
                        </Popup>}
                    </div>
                </div>
            </>
        );
    }else{
        return (
            <>
                <div className="navbar">
                    <Link to='/' className="navbar-title">
                        <img src={logo} className={'logo'} alt={logo}/>
                        <div className={'title'}>UniAdvisor.it</div>
                    </Link>
                    <SearchBar professorList={professorList} isHome={isHome} onChangeProfessor={onChangeProfessor}/>
                    <div className="menu-content">
                        <Button buttonStyle='btn--outline' onClick={handleOpenLoginForm}>ACCEDI/REGISTRATI</Button>
                        {isOpenLoginForm && <Popup>
                            <div className={'form-content'}>
                                <TitlePopup titleText={'Siamo spiacenti!'} onClose={handleOpenLoginForm}/>
                                <p>Il sito è in fase di manutenzione e questa funzione non è al momento disponibile.</p>
                                <p>Ti chiediamo di lasciarci la mail in modo da poterti avvisare quando è pronto</p>
                                <input className={"form-input"} placeholder="Mail"/>
                                <div className={'form-buttons'}>
                                    <button className={'send-button'}>Invia</button>
                                </div>
                            </div>
                        </Popup>}
                    </div>
                </div>
            </>
        );
    }

}

export default Navbar;
